const response = $input.first().json;
const staticData = $getWorkflowStaticData('global');
if (!staticData.heldItems) staticData.heldItems = [];

let parsed;
try {
  let text = response.content[0].text;
  text = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();
  parsed = JSON.parse(text);
} catch (e) {
  return [{ json: { error: true, message: e.message, high_tasks: [], medium_held: 0, meeting_title: 'Parse Error' } }];
}

const highTasks = [];
const mediumTasks = [];
const tasks = parsed.tasks || [];

for (var i = 0; i < tasks.length; i++) {
  var task = tasks[i];
  if (task.confidence === 'high') {
    highTasks.push(task);
  } else if (task.confidence === 'medium') {
    mediumTasks.push(task);
    staticData.heldItems.push({
      title: task.title,
      meeting: parsed.meeting_title || 'Unknown',
      stored_at: new Date().toISOString()
    });
  }
}

var highTaskTitles = highTasks.map(function(t) { return t.title; });
var slackMessage = 'Processed: ' + (parsed.meeting_title || 'Unknown Meeting') + '\n' +
  'Would create ' + highTasks.length + ' tasks in Asana\n';
for (var j = 0; j < highTaskTitles.length; j++) {
  slackMessage += '  - ' + highTaskTitles[j] + '\n';
}
slackMessage += 'Held ' + mediumTasks.length + ' items for tonight digest';

return [{ json: {
  meeting_title: parsed.meeting_title || 'Unknown',
  date: parsed.date,
  attendees: parsed.attendees || [],
  decisions: parsed.decisions || [],
  high_tasks: highTasks,
  medium_held: mediumTasks.length,
  total_held_in_store: staticData.heldItems.length,
  slack_message: slackMessage
} }];

const staticData = $getWorkflowStaticData('global');
const heldItems = staticData.heldItems || [];

if (heldItems.length === 0) {
  return [{ json: { has_items: false, count: 0, digest_message: '' } }];
}

var lines = [heldItems.length + ' items held from today transcripts:'];
for (var i = 0; i < heldItems.length; i++) {
  lines.push((i + 1) + '. ' + heldItems[i].title + ' (from: ' + heldItems[i].meeting + ')');
}
lines.push('Tell Iris create 1,2 or skip all. Auto-expires in 24h.');

staticData.heldItems = [];

return [{ json: {
  has_items: true,
  count: heldItems.length,
  digest_message: lines.join('\n')
} }];

const webhookData = $('Receive Transcript').item.json.body || $('Receive Transcript').item.json;
const subject = webhookData.subject || webhookData.email_subject || 'Unknown Meeting';
const body = webhookData.body || webhookData.email_body || webhookData.transcript || '';

if (!body || body.length < 100) {
  return [];
}

const prompt = `Review the following meeting transcript for knowledge that should be captured in runbooks.

IMPORTANT: "UCAPI" and "Universal Conversion API" are deprecated names — always use "VCAPI" or "VCAPy" in any runbook content.

Meeting: ${subject}

Instructions:
1. Read the transcript below
2. Check existing runbooks in ~/vaults/MindPalace/Adquadrant/Runbook/ for relevant content
3. If the transcript contains platform procedures, troubleshooting steps, client-specific quirks, or technical discoveries not already in the runbooks — update or create the relevant runbook file
4. Keep updates concise — bullet points, not prose
5. If nothing in the transcript is runbook-worthy, do nothing

Transcript:
${body}`;

return [{
  json: {
    body: {
      command: "dispatch",
      payload: {
        agent: "theo",
        prompt: prompt
      }
    },
    meeting_title: subject
  }
}];

